final class CartyFrame extends ffi.Opaque {}

final class CartyModel extends ffi.Opaque {}

final class CartyOrthoMap extends ffi.Opaque {}

/// 4x4 ROW-MAJOR camera->world extrinsic, translation in the 4th column (ARCore)
final class CartyPose extends ffi.Struct {
  @ffi.Array.multi([16])
  external ffi.Array<ffi.Double> cam_to_world;
}

/// pinhole K in pixels, at the resolution of the image it describes
final class CartyIntrinsics extends ffi.Struct {
  @ffi.Double()
  external double fx_px;

  @ffi.Double()
  external double fy_px;

  @ffi.Double()
  external double cx_px;

  @ffi.Double()
  external double cy_px;
}

/// world-grid dimensions; caps are CARTY_GRID_MAX_N / CARTY_GRID_MAX_H
final class CartyGridShape extends ffi.Struct {
  @ffi.Int32()
  external int cells_per_side;

  @ffi.Int32()
  external int height_bands;

  /// metres per ground cell
  @ffi.Double()
  external double res_m;

  /// metres per height band
  @ffi.Double()
  external double band_m;
}

final class CartyWorldGrid extends ffi.Opaque {}

